/* Source module: grammar-expansion.js
 * Additional CEFR grammar topics and detailed teaching notes for existing lessons.
 * This file extends GRAMMAR_DATA instead of mixing teaching prose into the app engine.
 */
const GRAMMAR_GUIDE = {
  'A1|sein & haben': {
    when: 'Use sein for identity, origin, location, age-style descriptions with alt, and states. Use haben for possession and many fixed expressions such as Hunger, Durst and Zeit.',
    steps: ['Choose the subject pronoun first.', 'Memorise the irregular present form for that person.', 'Add the adjective or noun phrase after the verb.'],
    tip: 'Say “Ich bin 20 Jahre alt”, but “Ich habe Hunger”. German does not use one English-style “to be” pattern for every expression.',
    contrast: 'sein describes what or how someone is; haben says what someone has or experiences.'
  },
  'A1|Präsens (regular)': {
    when: 'Use Präsens for habits, facts, routines and many future plans when the time is clear.',
    steps: ['Remove -en from the infinitive: mach-en → mach-.', 'Add -e, -st, -t, -en, -t, -en.', 'For du and er/sie/es, check special spelling and stem changes in common verbs.'],
    tip: 'The verb ending must match the subject. Do not put the infinitive in a normal main clause.',
    contrast: 'Ich lerne Deutsch. / Morgen lerne ich auch Deutsch. The time word changes the position of the subject, not the verb’s second-position rule.'
  },
  'A1|Articles — der/die/das': {
    when: 'Learn each noun together with its article and plural form. Article gender is grammatical, not always logical.',
    steps: ['Use der for masculine nouns, die for feminine nouns, das for neuter nouns.', 'Use die for all plural nouns.', 'Learn common clues such as -ung and -heit (often feminine) and -chen (neuter), but memorise exceptions.'],
    tip: 'Flashcards should show “der Tisch, die Tische”, not only “Tisch”.',
    contrast: 'A grammatical gender does not tell you a person’s real-world gender: das Mädchen is neuter because of the ending -chen.'
  },
  'A1|Akkusativ': {
    when: 'Use accusative mainly for the direct object: the person or thing directly affected by the action. Also learn accusative after common prepositions such as für, ohne, durch, gegen and um.',
    steps: ['Find the subject and conjugated verb.', 'Ask “wen oder was?” to find the direct object.', 'Change masculine der/ein to den/einen; feminine, neuter and plural forms usually look the same in the article.'],
    tip: 'The visible change is easiest to notice with masculine nouns: Ich sehe den Hund.',
    contrast: 'Ich helfe dem Mann uses dative because helfen takes dative; Ich sehe den Mann uses accusative.'
  },
  'A1|Dativ': {
    when: 'Use dative with the recipient in many giving sentences, after dative verbs such as helfen and danken, and after dative prepositions such as mit, nach, bei, seit, von, zu and aus.',
    steps: ['Learn the verb or preposition together with its case.', 'Change der/ein to dem/einem, die/eine to der/einer, and plural die to den plus often -n on the noun.', 'Check if a dative noun already ends in -n or -s before adding another ending.'],
    tip: 'Memorise chunks: mit dem Bus, bei meiner Freundin, mit meinen Freunden.',
    contrast: 'Case follows the governing verb or preposition, not English word order.'
  },
  'A1|Modal verbs': {
    when: 'Use können, müssen, wollen, sollen, dürfen and mögen/möchten to express ability, necessity, intention, advice, permission and preference.',
    steps: ['Conjugate the modal verb in position 2.', 'Keep the main verb in the infinitive at the end.', 'In a question, move the modal verb to position 1.'],
    tip: 'Ich muss heute lernen. “lernen” stays at the end even when a time phrase is added.',
    contrast: 'dürfen = be allowed to; müssen = have to; sollen = should / be expected to.'
  },
  'A1|Perfekt': {
    when: 'Use Perfekt for most conversations about completed past events. Many movement or change-of-state verbs use sein; most other verbs use haben.',
    steps: ['Choose haben or sein from the verb and its meaning.', 'Build the Partizip II: often ge- + stem + -t for regular verbs, or an irregular participle.', 'Keep the participle at the end of the clause.'],
    tip: 'Movement alone is not the only test; compare Ich habe den Bus gefahren (I drove the bus) with Ich bin nach Hause gefahren (I travelled home).',
    contrast: 'Regular: gemacht. Irregular: gegangen. Separable: aufgestanden. Inseparable prefixes and verbs ending in -ieren normally have no ge-.'
  },
  'A1|Word order — position 2': {
    when: 'In a normal main clause, the conjugated verb occupies the second sentence position. Position counts units, not individual words.',
    steps: ['Choose one unit to place first: subject, time, place or object.', 'Put the conjugated verb next.', 'Place the subject after the verb if another unit starts the sentence.'],
    tip: 'Heute fahre ich nach Hause. “Heute” is position 1 and “fahre” is position 2.',
    contrast: 'A question with yes/no answer has the verb first: Fährst du heute? A subordinate clause sends the finite verb to the end.'
  },
  'A2|Possessives in Dativ': {
    when: 'Possessive words mein, dein, sein, ihr, unser, euer and Ihr take endings similar to ein after dative prepositions and dative verbs.',
    steps: ['Identify the noun’s gender and number.', 'Apply the dative ending: masculine/neuter -em, feminine -er, plural -en.', 'Remember that the plural noun often receives an extra -n if possible.'],
    tip: 'Read the whole phrase aloud: mit meinem Bruder, mit meiner Schwester, mit meinen Freunden.'
  },
  'A2|weil — reason': {
    when: 'Use weil to explain why something happens. It introduces a subordinate clause, so the conjugated verb goes to the end.',
    steps: ['Write the main clause.', 'Add a comma and weil.', 'Place the subject and other clause information before the conjugated verb at the end.'],
    tip: 'The same rule applies when the verb is a modal: weil ich heute arbeiten muss.',
    contrast: 'weil ich krank bin (verb at end) vs. denn ich bin krank (main-clause word order).'
  },
  'A2|dass — reported info': {
    when: 'Use dass to report a statement, opinion, feeling or information after verbs such as sagen, denken, hoffen, glauben and wissen.',
    steps: ['Start with the reporting clause.', 'Add a comma and dass.', 'Place the subject early and the conjugated verb at the end of the dass-clause.'],
    tip: 'The subject does not disappear after dass: Sie sagt, dass sie später kommt.',
    contrast: 'dass introduces a clause (“that”); das is an article or demonstrative (“the/that”).'
  },
  'A2|wenn — condition': {
    when: 'Use wenn for conditions, present/future situations and repeated events. It can mean “if” or “whenever”.',
    steps: ['Put wenn at the start of its clause.', 'Move the conjugated verb to the end of that clause.', 'If the wenn-clause starts the sentence, place the main-clause verb immediately after the comma.'],
    tip: 'Wenn ich Zeit habe, rufe ich dich an. / Ich rufe dich an, wenn ich Zeit habe.'
  },
  'A2|als vs. wenn': {
    when: 'Use als for one specific situation or period in the past. Use wenn for repeated past events, present/future time, or conditions.',
    steps: ['Ask if the event happened once in the past: choose als.', 'For “whenever”, “if”, now or future: choose wenn.', 'Remember that the verb goes to the end of both subordinate clauses.'],
    tip: 'Als ich klein war … describes one period of life. Immer wenn ich Oma besuchte … describes repetition.'
  },
  'A2|Indirect W-questions': {
    when: 'Use an indirect W-question after expressions such as Ich weiß nicht, Kannst du mir sagen …? and Ich möchte wissen …',
    steps: ['Keep the question word (wo, wann, warum, wie, wer).', 'Use normal subject-before-verb order inside the indirect clause.', 'Put the conjugated verb at the end.'],
    tip: 'Direct: Wo wohnt er? Indirect: Ich weiß nicht, wo er wohnt.'
  },
  'A2|ob — indirect yes/no': {
    when: 'Use ob when the embedded question has no question word and can be answered yes or no.',
    steps: ['Start with the main statement or question.', 'Add a comma and ob.', 'Use subject-first order, with the finite verb at the end.'],
    tip: 'Ich weiß nicht, ob sie heute kommt. Do not use wenn to translate “whether”.',
    contrast: 'ob = whether/if in an indirect question; wenn = if/when for a condition or time.'
  },
  'A2|deshalb — therefore': {
    when: 'Use deshalb to show a result. It is an adverb, so it can stand first while the conjugated verb remains second.',
    steps: ['Give the reason in one clause.', 'Start the next clause with deshalb.', 'Place the conjugated verb directly after deshalb, then the subject if needed.'],
    tip: 'Es regnet. Deshalb bleiben wir zu Hause.',
    contrast: 'weil introduces a reason and puts the verb last; deshalb introduces the result and keeps main-clause order.'
  },
  'A2|trotzdem — nevertheless': {
    when: 'Use trotzdem to show that something happens despite an obstacle or unexpected fact.',
    steps: ['State the obstacle.', 'Start the next main clause with trotzdem.', 'Put the conjugated verb next and then the subject.'],
    tip: 'Ich bin müde. Trotzdem gehe ich zum Unterricht.',
    contrast: 'obwohl introduces a subordinate clause (verb at end); trotzdem is an adverb (verb second).'
  },
  'A2|Modal verbs in Präteritum': {
    when: 'Use modal Präteritum commonly in spoken and written stories about past necessity, ability, permission or intention.',
    steps: ['Use the past stem: konnte, musste, wollte, sollte, durfte, mochte.', 'Add the normal personal ending.', 'Keep the dependent infinitive at the end when there is one.'],
    tip: 'Ich musste lange arbeiten. This is usually more natural than a complex Perfekt construction with two verbs.'
  },
  'A2|könnte — polite': {
    when: 'Use könnte/könnten to make requests, suggestions or possibilities softer and more polite.',
    steps: ['Use könnte for ich/er/sie/es and könnten for wir/sie/Sie.', 'Put the infinitive at the end if there is one.', 'Use bitte to make the request friendly, not demanding.'],
    tip: 'Könnten Sie mir bitte helfen? is a polite request, while Können Sie …? is more direct.'
  },
  'A2|sollte — advice': {
    when: 'Use sollte/solltest to give advice or say what would be sensible, rather than describing a strict obligation.',
    steps: ['Conjugate sollte for the subject.', 'Place the action verb in the infinitive at the end.', 'Use nicht to advise against an action: Du solltest nicht so spät schlafen gehen.'],
    tip: 'müssen = necessity; sollen = instruction/expectation; sollten = advice.'
  },
  'A2|Konjunktiv II general': {
    when: 'Use Konjunktiv II for imaginary situations, wishes, soft requests and polite offers.',
    steps: ['Memorise the frequent forms wäre, hätte and könnte.', 'For many other verbs, use würde + infinitive.', 'In a wenn-clause, the Konjunktiv form usually comes at the end.'],
    tip: 'Wenn ich mehr Zeit hätte, würde ich mehr lesen.',
    contrast: 'hatte is simple past (“had”); hätte is hypothetical (“would have”).'
  },
  'A2|Adjective endings (def article)': {
    when: 'An adjective before a noun changes its ending after der-words such as der, dieser, jeder and welcher.',
    steps: ['Find case, gender and number.', 'Notice that the article already shows many grammatical features.', 'Use -e in the small set of nominative singular and accusative feminine/neuter forms; use -en in most remaining forms.'],
    tip: 'Learn the whole phrase—der neue Film, den neuen Film, mit dem neuen Film—not only the ending rule.'
  },
  'A2|Adjective endings (ein-words)': {
    when: 'After ein-words (ein, kein, mein, dein, sein and similar), the adjective sometimes carries the gender/case signal that the article does not show.',
    steps: ['Find case, gender and number.', 'Check the article ending.', 'Use a strong adjective ending when the article has no ending in that position: ein guter Mann, ein gutes Kind.'],
    tip: 'Compare der gute Mann with ein guter Mann; the adjective takes -er because ein has no masculine nominative ending.'
  },
  'A2|ohne + Akkusativ': {
    when: 'Ohne always takes accusative in standard German.',
    steps: ['Find the noun phrase after ohne.', 'Use the accusative article and adjective/possessive endings.', 'Check masculine singular especially: ohne den/meinen alten Freund.'],
    tip: 'The English translation does not decide the German case; the preposition does.'
  },
  'A2|mit + Dativ': {
    when: 'Mit always takes dative. It can mean “with” a person/thing or describe a means of transport.',
    steps: ['Place mit before the noun phrase.', 'Change the article/possessive to dative.', 'For plural nouns, check whether the noun needs -n.'],
    tip: 'mit dem Zug, mit einer Freundin, mit meinen Eltern.'
  },
  'A2|Wo / Wohin / Woher': {
    when: 'Use wo for location, wohin for a destination, and woher for origin.',
    steps: ['Wo? describes a fixed location and commonly takes dative with two-way prepositions.', 'Wohin? expresses movement towards a destination and commonly takes accusative.', 'Woher? often uses aus or von.'],
    tip: 'Ich bin in der Schule (where?) but Ich gehe in die Schule (to where?).'
  },
  'A2|Position vs placement verbs': {
    when: 'German often distinguishes a state/position from the action of putting or placing something.',
    steps: ['Use stehen/liegen/sitzen/hängen for where something is.', 'Use stellen/legen/setzen/hängen for placing it somewhere.', 'With two-way prepositions, the state often uses dative and the placement action accusative.'],
    tip: 'Das Buch liegt auf dem Tisch. Ich lege das Buch auf den Tisch.'
  },
  'A2|Dativ + Akkusativ verbs': {
    when: 'Verbs such as geben, schicken, zeigen, erklären and schenken can use a recipient (dative) and a thing (accusative).',
    steps: ['Identify who receives it (dative) and what is transferred (accusative).', 'With two full noun phrases, dative often comes first.', 'With two pronouns, accusative normally comes before dative: Ich gebe es ihm.'],
    tip: 'Do not confuse the person with the direct object: Ich schenke meiner Mutter einen Schal.'
  },
  'A2|Relative clauses': {
    when: 'A relative clause adds information about a noun without starting a new sentence.',
    steps: ['Put a comma before the relative clause.', 'Choose the relative pronoun by gender/number from the noun, but choose its case from its job inside the relative clause.', 'Put the conjugated verb at the end.'],
    tip: 'Der Mann, den ich sehe, … uses den because the man is the direct object inside the relative clause.'
  },
  'A2|werden — full verb': {
    when: 'As a full verb, werden means “become/get”. It is also used to form the passive and Futur I, so identify which pattern is present.',
    steps: ['Becoming: werden + adjective/noun (Er wird müde).', 'Futur I: werden + infinitive (Er wird später kommen).', 'Passive: werden + Partizip II (Das Haus wird gebaut).'],
    tip: 'A noun after werden often describes a role or profession without ein: Sie wird Ärztin.'
  },
  'B1|Konjunktiv II hypothetical': {
    when: 'Use Konjunktiv II to talk about unreal or unlikely situations, imagined consequences and polite/softened language.',
    steps: ['Use wäre/hätte/könnte/müsste/sollte where available.', 'Use würde + infinitive for many other verbs.', 'In a hypothetical condition, put the Konjunktiv verb at the end of the wenn-clause.'],
    tip: 'Wenn ich mehr Geld hätte, würde ich eine längere Reise machen.',
    contrast: 'A real condition uses wenn + Präsens (Wenn ich Zeit habe, komme ich); an unreal condition uses Konjunktiv II.'
  },
  'B1|Passive voice': {
    when: 'Use Vorgangspassiv when the action or process matters more than who performs it. The agent can be added with von + dative.',
    steps: ['Choose the tense of werden.', 'Add the Partizip II at the end.', 'For Perfekt passive, use ist/sind + Partizip II + worden; do not use geworden in this pattern.'],
    tip: 'Aktiv: Die Firma baut das Haus. Passiv: Das Haus wird (von der Firma) gebaut.',
    contrast: 'Vorgangspassiv describes an event; Zustandspassiv with sein describes the resulting state.'
  }
};

