  level: 'A1', title: 'A1 Everyday Sentence Patterns', items: [
    {title:'W-questions and yes/no questions', explanation:'Use a question word to ask for a specific detail. In a yes/no question, start with the conjugated verb.', rule:'W-word + verb + subject + ...?\nWo wohnst du?\nVerb + subject + ...?\nWohnst du in Ahmedabad?', examples:[['Wie heißt du?','What is your name?'],['Woher kommen Sie?','Where are you from?'],['Hast du heute Zeit?','Do you have time today?']], mistakes:[['❌ Wo du wohnst?','✅ Wo wohnst du?']], exercise:{q:'___ heißt du?',options:['Was','Wie','Wo'],correct:1,why:'Wie heißt du? asks someone’s name.'}},
    {title:'Negation — nicht or kein', explanation:'Use kein to negate a noun phrase with an indefinite article or no article. Use nicht to negate verbs, adjectives, adverbs, definite noun phrases or the sentence as a whole.', rule:'kein + noun:\nIch habe keine Zeit.\nnicht + adjective:\nDas ist nicht teuer.\nverb/action:\nIch komme heute nicht.', examples:[['Ich habe kein Auto.','I do not have a car.'],['Der Kaffee ist nicht heiß.','The coffee is not hot.'],['Ich spreche heute nicht.','I am not speaking today.']], mistakes:[['❌ Ich habe nicht Auto.','✅ Ich habe kein Auto.']], exercise:{q:'Ich habe ___ Zeit.',options:['nicht','kein','keine'],correct:2,why:'Zeit is feminine: keine Zeit.'}},
    {title:'Indefinite articles — ein/eine', explanation:'Use ein/eine for “a/an”. The ending depends on the noun’s gender and grammatical case. The plural usually has no indefinite article.', rule:'Nominativ:\nein Mann · eine Frau · ein Kind\nAkkusativ:\neinen Mann · eine Frau · ein Kind', examples:[['Das ist ein Tisch.','That is a table.'],['Sie kauft eine Tasche.','She buys a bag.'],['Er sieht einen Hund.','He sees a dog.']], mistakes:[['❌ Ich kaufe ein Apfel.','✅ Ich kaufe einen Apfel.']], exercise:{q:'Das ist ___ Buch.',options:['der','ein','eine'],correct:1,why:'Buch is neuter: ein Buch.'}},
    {title:'Personal pronouns and verb agreement', explanation:'The verb ending changes to match the subject. Learn the pronoun and its verb form as a pair; Sie (formal you) uses the same verb form as sie (they).', rule:'ich lern-e\n du lern-st\n er/sie/es lern-t\nwir lern-en\nihr lern-t\nsie/Sie lern-en', examples:[['Ich lerne Deutsch.','I learn German.'],['Ihr wohnt in der Stadt.','You all live in the city.'],['Wo wohnen Sie?','Where do you live? (formal)']], mistakes:[['❌ Du lernen Deutsch.','✅ Du lernst Deutsch.']], exercise:{q:'Ihr ___ sehr gut Deutsch.',options:['spreche','sprecht','sprechen'],correct:1,why:'ihr takes -t: ihr sprecht.'}},
    {title:'Separable verbs in the present', explanation:'Many common verbs have a prefix that separates in a main clause. Conjugate the verb stem and place the prefix at the end.', rule:'anrufen → Ich rufe dich an.\naufstehen → Ich stehe um sieben Uhr auf.\neinkaufen → Wir kaufen heute ein.', examples:[['Der Zug kommt um neun Uhr an.','The train arrives at nine.'],['Sie ruft ihre Mutter an.','She calls her mother.']], mistakes:[['❌ Ich anrufe dich.','✅ Ich rufe dich an.']], exercise:{q:'Ich ___ um sieben Uhr ___. (aufstehen)',options:['stehe / auf','aufstehe / —','auf / stehe'],correct:0,why:'The conjugated stem is in position 2; the prefix goes to the end.'}},
    {title:'Imperative — instructions and requests', explanation:'Use the imperative to give instructions or make requests. The form depends on whether you speak to du, ihr or Sie; polite Sie keeps the pronoun after the verb.', rule:'du: Komm! / Lies!\nihr: Kommt! / Lest!\nSie: Kommen Sie bitte! / Lesen Sie bitte!', examples:[['Mach bitte die Tür zu.','Please close the door.'],['Warten Sie einen Moment.','Please wait a moment.']], mistakes:[['❌ Bitte Sie warten.','✅ Warten Sie bitte.']], exercise:{q:'___ Sie bitte langsam!',options:['Sprechen','Sprich','Sprecht'],correct:0,why:'Formal request: infinitive form + Sie.'}},
    {title:'Possessives — nominative and accusative', explanation:'mein, dein, sein, ihr, unser, euer and Ihr tell who something belongs to. Their endings follow ein-words and change with gender, number and case.', rule:'Nom.: mein Bruder · meine Tasche · mein Kind\nAkk.: meinen Bruder · meine Tasche · mein Kind', examples:[['Das ist meine Schwester.','That is my sister.'],['Ich besuche meinen Bruder.','I am visiting my brother.']], mistakes:[['❌ Ich sehe mein Bruder.','✅ Ich sehe meinen Bruder.']], exercise:{q:'Ich sehe ___ Bruder.',options:['mein','meinen','meinem'],correct:1,why:'Bruder is masculine accusative: meinen Bruder.'}}
  ]
